{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C49"],
      "claim": "Urapidil absolute bioavailability was 72% relative to intravenous formulation in healthy volunteers, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Bosentan absolute oral bioavailability was 50% after a 500 mg oral dose versus 250 mg i.v. in healthy male subjects, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Rigosertib absolute oral bioavailability was 13.9% in fed MDS patients at 560 mg, below the 20% threshold, providing contradictory food-dependent evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Most evidence molecules show absolute oral bioavailability values from 25% to 82%, all above the 20% threshold; the only sub-20 value is fed-state rigosertib (13.9%), while its fasting absolute F is about 35%, so the overall evidence favors high bioavailability with moderate confidence.",
  "evidence_gaps": [
    "Molecule 3 combines records for GSK1322322 and brigatinib under one label; the inconsistent brigatinib card was discounted as a provenance conflict.",
    "Molecule 10 combines records for acalabrutinib and abemaciclib under one label; the inconsistent abemaciclib card was discounted as a provenance conflict.",
    "Molecule 4 shows food-dependent absolute bioavailability (13.9% fed vs ~35% fasting), so fed-state exposure remains a threshold-relevant uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

